changeSet.sql:

insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'DashboardView', 'Dashboard', now());
insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'TanimlamalarMenu', 'Tanımlamalar', now());
insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'TaskController', 'Görevler', now());
insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'SistemAyarlariMenu', 'Sistem Ayarları', now());
insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'UserController', 'Kullanıcılar', now());
insert into s_permission (id, name, title, created_date) values
    (nextval('SEQ_S_PERMISSION'), 'RolAtamaController', 'Kullanıcılara Rol Atama', now());


insert into s_role_permission (role_id, permission_id)
select (select id from s_role where name = 'ADMIN'), p.id from s_permission p;

insert into s_role_permission (role_id, permission_id) values
    ((select id from s_role where name = 'INTERN'), (select id from s_permission where name = 'DashboardView')),
    ((select id from s_role where name = 'INTERN'), (select id from s_permission where name = 'TanimlamalarMenu')),
    ((select id from s_role where name = 'INTERN'), (select id from s_permission where name = 'TaskController'));

insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), null, 'Dashboard', '/dashboard', 'dashboard', 1, true, (select id from s_permission where name = 'DashboardView'), now());
insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), null, 'Tanımlamalar', null, 'tune', 10, true, (select id from s_permission where name = 'TanimlamalarMenu'), now());
insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Tanımlamalar' and parent_id is null), 'Görevler', '/gorevler', 'task_alt', 5, true, (select id from s_permission where name = 'TaskController'), now());
insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), null, 'Sistem Ayarları', null, 'settings', 20, true, (select id from s_permission where name = 'SistemAyarlariMenu'), now());
insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Sistem Ayarları' and parent_id is null), 'Kullanıcılar', null, 'group', 1, true, (select id from s_permission where name = 'UserController'), now());
insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Kullanıcılar' and parent_id = (select id from s_menu where title = 'Sistem Ayarları' and parent_id is null)), 'Kullanıcılara Rol Atama', '/sistem/rol-atama', 'manage_accounts', 1, true, (select id from s_permission where name = 'RolAtamaController'), now());
